/* Focused regression test for upstream ITS#9037.
 *
 * Intent: when a transaction holds a stale named-DBI handle and the named-DB
 * record is missing from the main DB, mdb_page_search() must report the invalid
 * handle as MDB_BAD_DBI instead of the ordinary MDB_NOTFOUND result.
 *
 * Trigger (single process, equivalent to another process dropping the named DB
 * without bumping this process' env->me_dbiseqs):
 *   1. create named DB "db1" and commit.
 *   2. delete the "db1" record from MAIN_DBI, bypassing mdb_drop()/dbiseqs.
 *   3. start a fresh txn, open the still-registered handle and do a cursor op.
 *      txn_renew0() marks the inherited handle DB_STALE and TXN_DBI_CHANGED()
 *      is false, so mdb_page_search() reaches the `if (!exact)` branch.
 *
 * Expected: rc == MDB_BAD_DBI after the fix; rc == MDB_NOTFOUND before it.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lmdb.h"

int main(int argc, char **argv)
{
	MDB_env *env;
	MDB_txn *txn;
	MDB_dbi dbi;
	MDB_cursor *mc;
	MDB_val key, data;
	int rc, expected;
	const char *path = "testdb-baddbi";

	if (argc > 1 && strcmp(argv[1], "baddbi") == 0)
		expected = MDB_BAD_DBI;
	else if (argc > 1 && strcmp(argv[1], "notfound") == 0)
		expected = MDB_NOTFOUND;
	else {
		fprintf(stderr, "usage: %s baddbi|notfound\n", argv[0]);
		return 2;
	}

	rc = mdb_env_create(&env);
	if (rc) { fprintf(stderr, "env_create %d\n", rc); return 2; }
	mdb_env_set_maxdbs(env, 16);
	rc = mdb_env_open(env, path, 0, 0664);
	if (rc) { fprintf(stderr, "env_open %d\n", rc); return 2; }

	/* 1. create named DB and commit */
	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) { fprintf(stderr, "begin1 %d\n", rc); return 2; }
	rc = mdb_dbi_open(txn, "db1", MDB_CREATE, &dbi);
	if (rc) { fprintf(stderr, "dbi_open %d\n", rc); return 2; }
	key.mv_str = "k"; key.mv_size = 1;
	data.mv_str = "v"; data.mv_size = 1;
	rc = mdb_put(txn, dbi, &key, &data, 0);
	if (rc) { fprintf(stderr, "put %d\n", rc); return 2; }
	rc = mdb_txn_commit(txn);
	if (rc) { fprintf(stderr, "commit1 %d\n", rc); return 2; }

	/* 2. delete the DB record from MAIN_DBI directly */
	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) { fprintf(stderr, "begin2 %d\n", rc); return 2; }
	key.mv_str = "db1"; key.mv_size = 3;
	rc = mdb_del(txn, MAIN_DBI, &key, NULL);
	if (rc) { fprintf(stderr, "del %d (%s)\n", rc, mdb_strerror(rc)); return 2; }
	rc = mdb_txn_commit(txn);
	if (rc) { fprintf(stderr, "commit2 %d\n", rc); return 2; }

	/* 3. stale handle + missing record -> cursor op */
	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) { fprintf(stderr, "begin3 %d\n", rc); return 2; }
	rc = mdb_cursor_open(txn, dbi, &mc);
	if (rc) { fprintf(stderr, "cursor_open %d\n", rc); return 2; }
	data.mv_data = NULL; data.mv_size = 0;
	rc = mdb_cursor_get(mc, &key, &data, MDB_FIRST);
	printf("mdb_cursor_get(MDB_FIRST) rc=%d (%s) expected=%d (%s)\n",
	    rc, mdb_strerror(rc), expected, mdb_strerror(expected));
	mdb_cursor_close(mc);
	mdb_txn_abort(txn);
	mdb_env_close(env);
	return (rc == expected) ? 0 : 1;
}

