input.content:
/* Focused regression test for upstream ITS#9037.
 *
 * Intent: when a transaction holds a stale named-DBI handle and the named-DB
 * record is missing from the main DB, mdb_page_search() must report the invalid
 * handle as MDB_BAD_DBI instead of the ordinary MDB_NOTFOUND result.
 *
 * Scenario (matches the real cross-process case):
 *   1. parent creates named DB "db1" and commits; keeps the DBI handle open.
 *   2. a separate helper process opens the same env, drops "db1" (mdb_drop del=1)
 *      and commits. The helper's env bookkeeping is process-local, so the
 *      parent's env->me_dbiseqs[dbi] is unchanged.
 *   3. parent starts a fresh txn: txn_renew0() marks the inherited DBI DB_STALE,
 *      TXN_DBI_CHANGED() is false, the MAIN_DBI record for "db1" is gone, so
 *      mdb_page_search() reaches the `if (!exact)` branch.
 *
 * Expected: rc == MDB_BAD_DBI after the fix; rc == MDB_NOTFOUND before it.
 *
 * usage:
 *   baddbi_test drop <dbdir>            (helper mode)
 *   baddbi_test baddbi|notfound <dbdir> (main mode; dbdir must already exist)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include "lmdb.h"

static int do_drop(const char *path)
{
	MDB_env *env;
	MDB_txn *txn;
	MDB_dbi dbi;
	int rc;

	rc = mdb_env_create(&env);
	if (rc) return rc;
	mdb_env_set_maxdbs(env, 16);
	rc = mdb_env_open(env, path, 0, 0664);
	if (rc) return rc;
	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) return rc;
	rc = mdb_dbi_open(txn, "db1", 0, &dbi);
	if (rc) return rc;
	rc = mdb_drop(txn, dbi, 1);
	if (rc) return rc;
	rc = mdb_txn_commit(txn);
	mdb_env_close(env);
	return rc;
}

int main(int argc, char **argv)
{
	MDB_env *env;
	MDB_txn *txn;
	MDB_dbi dbi;
	MDB_cursor *mc;
	MDB_val key, data;
	int rc, expected;
	char cmd[4096];
	const char *path;

	if (argc < 3) {
		fprintf(stderr, "usage: %s drop <dbdir> | baddbi|notfound <dbdir>\n", argv[0]);
		return 2;
	}
	path = argv[2];

	if (strcmp(argv[1], "drop") == 0)
		return do_drop(path) ? 2 : 0;

	if (strcmp(argv[1], "baddbi") == 0)
		expected = MDB_BAD_DBI;
	else if (strcmp(argv[1], "notfound") == 0)
		expected = MDB_NOTFOUND;
	else {
		fprintf(stderr, "unknown mode %s\n", argv[1]);
		return 2;
	}

	rc = mdb_env_create(&env);
	if (rc) { fprintf(stderr, "env_create %d\n", rc); return 2; }
	mdb_env_set_maxdbs(env, 16);
	rc = mdb_env_open(env, path, 0, 0664);
	if (rc) { fprintf(stderr, "env_open %d\n", rc); return 2; }

	/* 1. create named DB and commit; keep the handle registered */
	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) { fprintf(stderr, "begin1 %d\n", rc); return 2; }
	rc = mdb_dbi_open(txn, "db1", MDB_CREATE, &dbi);
	if (rc) { fprintf(stderr, "dbi_open %d\n", rc); return 2; }
	key.mv_data = "k"; key.mv_size = 1;
	data.mv_data = "v"; data.mv_size = 1;
	rc = mdb_put(txn, dbi, &key, &data, 0);
	if (rc) { fprintf(stderr, "put %d\n", rc); return 2; }
	rc = mdb_txn_commit(txn);
	if (rc) { fprintf(stderr, "commit1 %d\n", rc); return 2; }

	/* 2. separate process drops the named DB */
	snprintf(cmd, sizeof cmd, "'%s' drop '%s'", argv[0], path);
	rc = system(cmd);
	if (rc != 0) { fprintf(stderr, "helper drop failed: %d\n", rc); return 2; }

	/* 3. stale handle + missing record -> cursor op */
	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) { fprintf(stderr, "begin3 %d\n", rc); return 2; }
	rc = mdb_cursor_open(txn, dbi, &mc);
	if (rc) { fprintf(stderr, "cursor_open %d\n", rc); return 2; }
	data.mv_data = NULL; data.mv_size = 0;
	rc = mdb_cursor_get(mc, &key, &data, MDB_FIRST);
	printf("mdb_cursor_get(MDB_FIRST) rc=%d (%s) expected=%d (%s)\n",
	    rc, mdb_strerror(rc), expected, mdb_strerror(expected));
	mdb_cursor_close(mc);
	mdb_txn_abort(txn);
	mdb_env_close(env);
	return (rc == expected) ? 0 : 1;
}

