input.content:
/* Positive-path control for the mdb_page_search() DB_STALE root-refresh path.
 *
 * Creates a named DB, commits, then in a fresh txn opens the still-registered
 * handle (txn_renew0 marks it DB_STALE). The MAIN_DBI record is present, so
 * mdb_page_search() must read it, refresh mc->mc_db and clear DB_STALE, and the
 * subsequent MDB_FIRST must return the stored value. This path is unchanged by
 * the ITS#9037 fix and must keep working.
 */
#include <stdio.h>
#include <string.h>
#include "lmdb.h"

int main(int argc, char **argv)
{
	MDB_env *env;
	MDB_txn *txn;
	MDB_dbi dbi;
	MDB_cursor *mc;
	MDB_val key, data;
	int rc;
	const char *path = (argc > 1) ? argv[1] : "testdb-positive";

	rc = mdb_env_create(&env);
	if (rc) return 2;
	mdb_env_set_maxdbs(env, 16);
	rc = mdb_env_open(env, path, 0, 0664);
	if (rc) return 2;

	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) return 2;
	rc = mdb_dbi_open(txn, "db1", MDB_CREATE, &dbi);
	if (rc) return 2;
	key.mv_data = "k"; key.mv_size = 1;
	data.mv_data = "v"; data.mv_size = 1;
	rc = mdb_put(txn, dbi, &key, &data, 0);
	if (rc) return 2;
	rc = mdb_txn_commit(txn);
	if (rc) return 2;

	/* fresh txn: handle is DB_STALE, record present -> refresh must succeed */
	rc = mdb_txn_begin(env, NULL, 0, &txn);
	if (rc) return 2;
	rc = mdb_cursor_open(txn, dbi, &mc);
	if (rc) return 2;
	data.mv_data = NULL; data.mv_size = 0;
	rc = mdb_cursor_get(mc, &key, &data, MDB_FIRST);
	printf("positive MDB_FIRST rc=%d (%s) size=%zu\n",
	    rc, mdb_strerror(rc), data.mv_size);
	mdb_cursor_close(mc);
	mdb_txn_abort(txn);
	mdb_env_close(env);
	return (rc == MDB_SUCCESS) ? 0 : 1;
}

